tool_input.command:
$ErrorActionPreference='SilentlyContinue'
Write-Output "== direct connectivity test =="
foreach($u in 'https://push2.eastmoney.com/api/qt/stock/get','https://qt.gtimg.cn/q=sh600000','https://hq.sinajs.cn/list=sh600000'){
  try { $r=Invoke-WebRequest -Uri $u -TimeoutSec 8 -UseBasicParsing; "$u -> $($r.StatusCode)" } catch { "$u -> ERR $($_.Exception.Message)" }
}

Write-Output "== 筛选结果相关 csv =="; Get-ChildItem '分析产出' -Filter '*.csv' | Where-Object {$_.Name -match '筛选|漏斗|明细|替补|主池|组合|专用'} | Sort-Object LastWriteTime -Descending | Select-Object LastWriteTime,Name
Write-Output "== screen_sz OUT names =="; Select-String -Path '分析产出\screen_sz.py' -Pattern "^OUT|^DETAIL|^FUNNEL|^LAKE" | ForEach-Object {$_.Line}
Write-Output "== progress 2026-10-29 status fields =="; python -c "import json;d=json.load(open(r'logs/selection_update/progress-2026-10-29.json',encoding='utf-8'));print({k:v.get('status') for k,v in d.get('stages',{}).items()});print('date',d.get('date'))"

$ErrorActionPreference='SilentlyContinue'
$ok=$false
for($i=0;$i -lt 12;$i++){
  $r=Test-NetConnection -ComputerName 127.0.0.1 -Port 7890 -WarningAction SilentlyContinue
  if($r.TcpTestSucceeded){$ok=$true;break}
  Start-Sleep -Seconds 5
}
if($ok){
  Write-Output "PROXY_UP"
  try { $t=Invoke-WebRequest -Uri 'https://datacenter.eastmoney.com' -Proxy 'http://127.0.0.1:7890' -TimeoutSec 10 -UseBasicParsing; "proxy egress -> $($t.StatusCode)" } catch { "proxy egress err: $($_.Exception.Message)" }
} else { Write-Output "PROXY_DOWN_STILL" }

$ErrorActionPreference='SilentlyContinue'
$ok=$false
for($i=0;$i -lt 24;$i++){
  $r=Test-NetConnection -ComputerName 127.0.0.1 -Port 7890 -WarningAction SilentlyContinue
  if($r.TcpTestSucceeded){$ok=$true;break}
  Start-Sleep -Seconds 5
}
if($ok){Write-Output "PROXY_UP"}else{Write-Output "PROXY_DOWN_STILL"}
Get-Process | Where-Object {$_.ProcessName -match 'clash|v2ray|sing-box|xray|verge|mihomo|nekoray|proxy'} | Select-Object ProcessName,Id
